from pathlib import Path
import hashlib,json
roots=[Path('products/sites/parser-parity-review'),Path('products/services/parser-parity')]
files={}
for root in roots:
 for p in sorted(root.rglob('*')):
  if p.is_file():
   b=p.read_bytes()
   files[str(p)]={'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'text':b.decode('utf-8')}
out=Path('products/reviews/parser-parity-source-inspection.json')
out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(json.dumps({'purpose':'Independent source inspection inventory; no review verdict or customer outcome established','files':files},ensure_ascii=False,indent=2))
print(out.read_text())
